diff --git a/src/script/sign.h b/src/script/sign.h
index 107abb9e84..b1e7e24339 100644
--- a/src/script/sign.h
+++ b/src/script/sign.h
@@ -33,6 +33,8 @@ struct SignatureData;

 struct SignOptions {
     int sighash_type{SIGHASH_DEFAULT};
+    //! BIP340 auxiliary randomness. Fresh randomness is used if unset.
+    std::optional<uint256> aux_rand{std::nullopt};
 };

 /** Interface for signature creators. */
diff --git a/src/test/fuzz/script_sign.cpp b/src/test/fuzz/script_sign.cpp
index be7c2d2898..7750f5615e 100644
--- a/src/test/fuzz/script_sign.cpp
+++ b/src/test/fuzz/script_sign.cpp
@@ -13,6 +13,7 @@
 #include <test/fuzz/FuzzedDataProvider.h>
 #include <test/fuzz/fuzz.h>
 #include <test/fuzz/util.h>
+#include <test/util/random.h>
 #include <test/util/transaction_utils.h>
 #include <util/chaintype.h>
 #include <util/translation.h>
@@ -33,6 +34,7 @@ void initialize_script_sign()

 FUZZ_TARGET(script_sign, .init = initialize_script_sign)
 {
+    SeedRandomStateForTest(SeedRand::ZEROS);
     FuzzedDataProvider fuzzed_data_provider(buffer.data(), buffer.size());
     const std::vector<uint8_t> key = ConsumeRandomLengthByteVector(fuzzed_data_provider, 128);

diff --git a/src/script/sign.cpp b/src/script/sign.cpp
index 3b382543b5..f098d0ecbe 100644
--- a/src/script/sign.cpp
+++ b/src/script/sign.cpp
@@ -14,6 +14,7 @@
 #include <policy/policy.h>
 #include <prevector.h>
 #include <primitives/transaction.h>
+#include <random.h>
 #include <script/keyorigin.h>
 #include <script/miniscript.h>
 #include <script/script.h>
@@ -114,8 +115,9 @@ bool MutableTransactionSignatureCreator::CreateSchnorrSig(const SigningProvider&
     if (!hash.has_value()) return false;

     sig.resize(64);
-    // Use uint256{} as aux_rnd for now.
-    if (!key.SignSchnorr(*hash, sig, merkle_root, {})) return false;
+    // BIP340 recommends fresh randomness as auxiliary data.
+    const uint256 aux_rand{m_options.aux_rand.value_or(GetRandHash())};
+    if (!key.SignSchnorr(*hash, sig, merkle_root, aux_rand)) return false;
     if (m_options.sighash_type) sig.push_back(m_options.sighash_type);
     return true;
 }
diff --git a/src/test/script_tests.cpp b/src/test/script_tests.cpp
index e6e0744fff..995f6d7088 100644
--- a/src/test/script_tests.cpp
+++ b/src/test/script_tests.cpp
@@ -1678,14 +1678,21 @@ BOOST_AUTO_TEST_CASE(bip341_keypath_test_vectors)
             XOnlyPubKey pubkey{key.GetPubKey()};
             BOOST_CHECK_EQUAL(HexStr(pubkey), input["intermediary"]["internalPubkey"].get_str());

-            // Sign and verify signature.
+            // Sign and verify signature. The vectors use all-zero auxiliary randomness.
             FlatSigningProvider provider;
             provider.keys[key.GetPubKey().GetID()] = key;
-            MutableTransactionSignatureCreator creator(tx, txinpos, utxos[txinpos].nValue, &txdata, {.sighash_type = hashtype});
+            MutableTransactionSignatureCreator creator(tx, txinpos, utxos[txinpos].nValue, &txdata, {.sighash_type = hashtype, .aux_rand = uint256{}});
             std::vector<unsigned char> signature;
             BOOST_CHECK(creator.CreateSchnorrSig(provider, signature, pubkey, nullptr, &merkle_root, SigVersion::TAPROOT));
             BOOST_CHECK_EQUAL(HexStr(signature), input["expected"]["witness"][0].get_str());

+            // By default, fresh auxiliary randomness makes the signatures differ.
+            MutableTransactionSignatureCreator random_creator(tx, txinpos, utxos[txinpos].nValue, &txdata, {.sighash_type = hashtype});
+            std::vector<unsigned char> random_sig1, random_sig2;
+            BOOST_CHECK(random_creator.CreateSchnorrSig(provider, random_sig1, pubkey, nullptr, &merkle_root, SigVersion::TAPROOT));
+            BOOST_CHECK(random_creator.CreateSchnorrSig(provider, random_sig2, pubkey, nullptr, &merkle_root, SigVersion::TAPROOT));
+            BOOST_CHECK(random_sig1 != random_sig2);
+
             // We can't observe the tweak used inside the signing logic, so verify by recomputing it.
             BOOST_CHECK_EQUAL(HexStr(pubkey.ComputeTapTweakHash(merkle_root.IsNull() ? nullptr : &merkle_root)), input["intermediary"]["tweak"].get_str());


